                  <p className="max-w-[68ch] pb-5 text-sm leading-relaxed text-fg-2">
                    {a}
                    {more && (
                      <>
                        {" "}
                        <a href={more.href} className="font-medium text-accent-text underline-offset-4 hover:underline">
                          {more.label}
                        </a>
                      </>
                    )}
                  </p>
                </details>
              ))}
            </div>
          </div>
        </section>

        {/* Inverted close, matching the service pages. The nav's Contact link
            is a bare #contact fragment, so every public route carries the
            anchor - this section is it. */}
        <div data-theme="dark" className="band">
          <ContactCta
            heading="Ready to put a number on it?"
            sub="Tell us what you're working on. You'll hear back within one business day, with a firm quote."
          />
        </div>
      </main>
    </>
  );
}

